    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  issueInvoice(invoice, []);
  assert.equal(invoice.status, 'draft');
